{
  "reference_answer": "I do enjoy cooking, though I'd say I'm more of a weekend cook than a daily one. During the week I'm usually too wiped out to do anything fancy, so it's mostly quick pasta or something I can throw together in twenty minutes. But on weekends, I like taking my time — trying out a new recipe, chopping everything properly, that sort of thing. What I really enjoy is the process itself; it's a nice way to switch off from screens and just focus on one task. Plus, there's something satisfying about making a meal from scratch and actually tasting the difference. I wouldn't call myself a great cook, but I've definitely improved over the past couple of years, mainly because I got tired of ordering takeout all the time.",
  "reference_angle_summary": "独立主线：以“周末做饭 vs 工作日凑合”的对比展开，强调做饭作为放松方式和技能成长；示例不代表用户经历。",
  "takeaway_expressions": [
    {
      "expression": "more of a weekend cook than a daily one",
      "meaning_zh": "更像是周末做饭的人，而不是每天做饭的人",
      "why_useful": "用对比结构自然说明习惯频率，比直接说 sometimes 更具体、更像真实口语。",
      "example": "I'm more of a weekend runner than a daily one — I just can't fit it in on workdays.",
      "usage_note": "可套用为 more of a ... than a ...，替换活动或身份即可。"
    },
    {
      "expression": "switch off from screens",
      "meaning_zh": "从屏幕中抽离、放松下来",
      "why_useful": "描述放松原因时很自然，避免只说 it is relaxing，能具体到现代生活场景。",
      "example": "Gardening helps me switch off from screens after a long day.",
      "usage_note": "switch off 常与 from 搭配，也可说 switch off mentally。"
    },
    {
      "expression": "from scratch",
      "meaning_zh": "从零开始（尤指做饭不用现成材料）",
      "why_useful": "高频口语短语，谈做饭、学习、项目都能用，显得地道。",
      "example": "I made the soup from scratch instead of using a packet.",
      "usage_note": "固定搭配，不加 the 或 a。"
    }
  ]
}

